// tests/api/decode-multicall.test.js
import { describe, it, expect, vi, beforeEach, afterEach } from "vitest";
import { GET } from "../../app/api/decode/route.js";
import {
  serverCacheTestDir,
  resetServerCacheTestDir,
  removeServerCacheTestDir,
} from "../utils/serverCacheTestEnv.js";

const CACHE_DIR = serverCacheTestDir("decode-multicall");

// ---------------------------------------------------------------------------
// Integration tests for GET /api/decode — multicall and Universal Router
// augmentation. Mocks the D1 Worker (empty candidates) and Sourcify (inner
// call name resolution) but runs the real client-side multicall/UR decoders.
// ---------------------------------------------------------------------------

// 1. multicall((address,bytes,uint256,bool,bytes32)[]) — tuple_array
const TUPLE_ARRAY_DATA =
  "";

// 2. multicall(bytes[]) — bytes_array
const BYTES_ARRAY_DATA =
  "";

// 2b. execute((address,uint256,bytes)[],bytes32) — tuple_array + bytes32
const EXECUTE_TUPLE_DATA =
  "";

// 3. execute(bytes,bytes[]) — Universal Router, no deadline
const UR_NO_DEADLINE_DATA =
  "";

// 4. execute(bytes,bytes[],uint256) — Universal Router with deadline
const UR_WITH_DEADLINE_DATA =
  "";

// 5. Regular function — no multicall
const NORMAL_DATA =
  "0x3244c12c000000000000000000000000000000000000000000000000030d98d59a960000000000000000000000000000b98c948cfa24072e58935bc004a8a7b376ae746a";

const SOURCIFY_SIGNATURES = {
  "0x3244c12c": ["wrapNative(uint256,address)"],
  "0x6ef5eeae": ["erc4626Deposit(address,uint256,uint256,address)"],
  "0xdb3e2198": [
    "exactInputSingle((address,address,uint24,address,uint256,uint256,uint256,uint160))",
  ],
  "0x12210e8a": ["refundETH()"],
};

function makeRequest(data) {
  const url = new URL("http://localhost/api/decode");
  url.searchParams.set("data", data);
  return { url: url.toString() };
}

// Handles both the D1 Worker's /api/v1/query?sign= calls (always "no match",
// since sign= never appears in the Sourcify-style regex below) and Sourcify's
// ?function= calls.
function mockSourcify(signatures) {
  return (url) => {
    const selectorMatch = url.match(/function=(0x[0-9a-fA-F]{8})/);
    if (!selectorMatch)
      return Promise.resolve({
        ok: true,
        json: async () => ({ ok: true, result: { function: {} } }),
      });
    const selector = selectorMatch[1];
    const names = signatures[selector] || [];
    return Promise.resolve({
      ok: true,
      json: async () => ({
        ok: true,
        result: {
          function: {
            [selector]: names.map((n) => ({ name: n, filtered: false })),
          },
        },
      }),
    });
  };
}

beforeEach(async () => {
  process.env.CACHE_DIR = CACHE_DIR;
  await resetServerCacheTestDir(CACHE_DIR);
  vi.stubGlobal("fetch", vi.fn());
  process.env.BACKEND_URL = "https://backend.test";
});

afterEach(async () => {
  vi.unstubAllGlobals();
  delete process.env.BACKEND_URL;
  delete process.env.CACHE_DIR;
  await removeServerCacheTestDir(CACHE_DIR);
});

describe("GET /api/decode — multicall augmentation", () => {
  it("multicall((address,bytes,uint256,bool,bytes32)[]) — 3 inner calls", async () => {
    global.fetch.mockImplementation(mockSourcify(SOURCIFY_SIGNATURES));

    const res = await GET(makeRequest(TUPLE_ARRAY_DATA));
    expect(res.status).toBe(200);
    const body = await res.json();
    const d0 = body.data[0];

    expect(d0.func).toBe("multicall((address,bytes,uint256,bool,bytes32)[])");
    expect(d0.inner_calls).toHaveLength(3);
    expect(d0.inner_calls[0].selector).toBeNull();
    expect(d0.inner_calls[1].selector).toBe("0x3244c12c");
    expect(d0.inner_calls[2].selector).toBe("0x6ef5eeae");
    expect(d0.inner_calls[1].decoded.func).toBe("wrapNative(uint256,address)");
    expect(d0.inner_calls[2].decoded.func).toBe(
      "erc4626Deposit(address,uint256,uint256,address)",
    );
  });

  it("multicall(bytes[]) — 2 inner calls", async () => {
    global.fetch.mockImplementation(mockSourcify(SOURCIFY_SIGNATURES));

    const res = await GET(makeRequest(BYTES_ARRAY_DATA));
    expect(res.status).toBe(200);
    const body = await res.json();
    const d0 = body.data[0];

    expect(d0.func).toBe("multicall(bytes[])");
    expect(d0.inner_calls).toHaveLength(2);
    expect(d0.inner_calls[0].selector).toBe("0xdb3e2198");
    expect(d0.inner_calls[1].selector).toBe("0x12210e8a");
    expect(d0.inner_calls[1].decoded.func).toBe("refundETH()");
  });

  it("execute((address,uint256,bytes)[],bytes32) — 3 inner calls with targets/values", async () => {
    global.fetch.mockImplementation(mockSourcify(SOURCIFY_SIGNATURES));

    const res = await GET(makeRequest(EXECUTE_TUPLE_DATA));
    expect(res.status).toBe(200);
    const body = await res.json();
    const d0 = body.data[0];

    expect(d0.func).toBe("execute((address,uint256,bytes)[],bytes32)");
    expect(d0.args.commit).toBe(
      "0x00000000000000000000000000000000019eb604f27d700bb64910ebcbef71ee",
    );
    expect(d0.args.calls).toHaveLength(3);
    expect(d0.inner_calls).toHaveLength(3);

    expect(d0.inner_calls[0].target).toBe(
      "0x60FccB9b58d5E806ca5Cb8BFCe721c2274609dE4",
    );
    expect(d0.inner_calls[0].value).toBe(0);
    expect(d0.inner_calls[0].selector).toBe("0x3244c12c");
    expect(d0.inner_calls[0].decoded.func).toBe("wrapNative(uint256,address)");

    expect(d0.inner_calls[1].target).toBe(
      "0x904861a24F30EC96ea7CFC3bE9EA4B476d237e98",
    );
    expect(d0.inner_calls[1].value).toBe("11974268881699143");
    expect(d0.inner_calls[1].selector).toBe("0x12210e8a");
    expect(d0.inner_calls[1].decoded.func).toBe("refundETH()");

    expect(d0.inner_calls[2].target).toBe(
      "0x8E60b7b64b63cD56b18ebcECADcb79B04919286e",
    );
    expect(d0.inner_calls[2].selector).toBeNull();
    expect(d0.inner_calls[2].data).toBe("0x");
  });

  it("execute(bytes,bytes[]) — Universal Router, 5 commands", async () => {
    global.fetch.mockImplementation(mockSourcify(SOURCIFY_SIGNATURES));

    const res = await GET(makeRequest(UR_NO_DEADLINE_DATA));
    expect(res.status).toBe(200);
    const body = await res.json();
    const d0 = body.data[0];

    expect(d0.func).toBe("execute(bytes,bytes[])");
    expect(d0.inner_calls).toHaveLength(5);
    expect(d0.inner_calls[0].name).toBe("V3_SWAP_EXACT_IN");
    expect(d0.inner_calls[1].name).toBe("PERMIT2_TRANSFER_FROM_BATCH");
    expect(d0.inner_calls[2].name).toBe("V2_SWAP_EXACT_OUT");
    expect(d0.inner_calls[3].name).toBe("UNKNOWN_0x0f");
    expect(d0.inner_calls[4].name).toBe("PERMIT2_TRANSFER_FROM");
  });

  it("execute(bytes,bytes[],uint256) — Universal Router with deadline, 3 commands", async () => {
    global.fetch.mockImplementation(mockSourcify(SOURCIFY_SIGNATURES));

    const res = await GET(makeRequest(UR_WITH_DEADLINE_DATA));
    expect(res.status).toBe(200);
    const body = await res.json();
    const d0 = body.data[0];

    expect(d0.func).toBe("execute(bytes,bytes[],uint256)");
    expect(d0.inner_calls).toHaveLength(3);
    expect(d0.inner_calls[0].name).toBe("WRAP_ETH");
    expect(d0.inner_calls[1].name).toBe("V3_SWAP_EXACT_IN");
    expect(d0.inner_calls[2].name).toBe("SWEEP");
  });

  it("regular function — no inner_calls", async () => {
    global.fetch.mockImplementation(mockSourcify(SOURCIFY_SIGNATURES));

    const res = await GET(makeRequest(NORMAL_DATA));
    expect(res.status).toBe(200);
    const body = await res.json();
    const d0 = body.data[0];

    expect(d0.func).toBe("wrapNative(uint256,address)");
    expect(d0.source).toBe("sourcify");
    expect(d0.inner_calls).toBeUndefined();
  });
});
